<?php
require_once __DIR__ . '/../helpers/auth.php'; requireLogin();
require_once __DIR__ . '/../models/ProductoModel.php'; require_once __DIR__ . '/../models/CompraModel.php';
$pm=new ProductoModel(); $productos=$pm->obtenerTodos(); $proveedores=$pm->obtenerProveedores(); $compras=(new CompraModel())->recientes();
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compras - Mi Stock</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head>
<body class="bg-light"><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-3"><h2>📥 Registrar compra</h2><a href="dashboard.php" class="btn btn-outline-secondary">Volver</a></div><?php if(!empty($_GET['ok'])):?><div class="alert alert-success"><?=e($_GET['ok'])?></div><?php endif;?><?php if(!empty($_GET['error'])):?><div class="alert alert-danger"><?=e($_GET['error'])?></div><?php endif;?>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><form id="formCompra" action="../controllers/CompraController.php" method="post" enctype="multipart/form-data"><div class="row g-3"><div class="col-md-4"><label class="form-label">Proveedor</label><select class="form-select" name="proveedor" required><?php foreach($proveedores as $p):?><option value="<?=$p['IdProveedor']?>"><?=e($p['Nombre'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Documento</label><select name="tipo_documento" class="form-select"><option>FACTURA</option><option>BOLETA</option><option>OTRO</option></select></div><div class="col-md-3"><label class="form-label">N° documento</label><input name="numero_documento" class="form-control"></div><div class="col-md-3"><label class="form-label">Adjuntar boleta/factura</label><input type="file" name="documento" class="form-control" accept=".pdf,.png,.jpg,.jpeg"></div></div><hr><div class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label">Producto</label><select id="prod" class="form-select"><?php foreach($productos as $p):?><option value="<?=$p['IdProducto']?>" data-nombre="<?=e($p['Nombre'])?>" data-precio="<?=$p['PrecioCompra']?>"><?=e($p['Codigo'].' - '.$p['Nombre'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Cantidad</label><input id="cant" type="number" min="1" value="1" class="form-control"></div><div class="col-md-2"><label class="form-label">Precio unitario</label><input id="precio" type="number" min="0" step="0.01" class="form-control"></div><div class="col-md-2"><button type="button" class="btn btn-primary w-100" onclick="agregar()">Agregar</button></div></div><div class="table-responsive mt-3"><table class="table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Subtotal</th><th></th></tr></thead><tbody id="det"></tbody></table></div><div class="d-flex justify-content-between fw-bold fs-5"><span>Total compra</span><span id="total">$0</span></div><input type="hidden" name="detalles_json" id="detjson"><input type="hidden" name="total" id="totalInput"><button class="btn btn-success mt-3">Guardar compra y aumentar stock</button></form></div></div>
<div class="card border-0 shadow-sm"><div class="card-header bg-white fw-bold">Compras recientes</div><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-dark"><tr><th>Fecha</th><th>Proveedor</th><th>Documento</th><th>Total</th><th>Archivo</th></tr></thead><tbody><?php foreach($compras as $c):?><tr><td><?=date('d/m/Y H:i',strtotime($c['FechaCompra']))?></td><td><?=e($c['Proveedor'])?></td><td><?=e($c['TipoDocumento'].' '.($c['NumeroDocumento']??''))?></td><td>$<?=number_format((float)$c['Total'],0,',','.')?></td><td><?php if($c['ArchivoDocumento']):?><a href="../uploads/documentos/<?=rawurlencode($c['ArchivoDocumento'])?>" target="_blank">Ver documento</a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
</div><script>let items=[];const money=n=>n.toLocaleString('es-CL',{maximumFractionDigits:0});function agregar(){let s=document.getElementById('prod'),o=s.options[s.selectedIndex],id=+s.value,n=o.dataset.nombre,precio=+(document.getElementById('precio').value||o.dataset.precio||0),cantidad=+document.getElementById('cant').value;if(cantidad<1)return;if(!items.find(x=>x.id_producto===id))items.push({id_producto:id,nombre:n,cantidad,precio_unitario:precio});else{let x=items.find(x=>x.id_producto===id);x.cantidad+=cantidad;x.precio_unitario=precio;}render();}function quitar(id){items=items.filter(x=>x.id_producto!==id);render();}function render(){let b=document.getElementById('det'),t=0;b.innerHTML='';items.forEach(x=>{let s=x.cantidad*x.precio_unitario;t+=s;b.innerHTML+=`<tr><td>${x.nombre}</td><td>${x.cantidad}</td><td>$${money(x.precio_unitario)}</td><td>$${money(s)}</td><td><button type="button" class="btn btn-sm btn-danger" onclick="quitar(${x.id_producto})">×</button></td></tr>`});document.getElementById('total').innerText='$'+money(t);document.getElementById('totalInput').value=t;document.getElementById('detjson').value=JSON.stringify(items);}</script></body></html>
